contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v, uint amount, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        c.SetMinSum(v); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint callerBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        require(v <= callerBefore);
        require(am <= callerBefore);

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint callerAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(!reverted && callerAfter == callerBefore - am);
    }

    receive() external payable {}
}

